"""JWT 발급/검증 (pyjwt, HS256)."""
import os
import time

import jwt


_DEFAULT_SECRET = "dev-insecure-secret-change-me-in-production-32b"
_ALG = "HS256"
_ISSUER = "saju-auth"


def _secret() -> str:
    s = os.environ.get("SAJU_JWT_SECRET", "").strip()
    if s:
        return s
    if os.environ.get("SAJU_ENV", "").lower() == "production":
        raise RuntimeError(
            "SAJU_JWT_SECRET must be set in production. "
            "The default development secret must not be used in deployment."
        )
    return _DEFAULT_SECRET


def ttl_seconds() -> int:
    try:
        return int(os.environ.get("SAJU_JWT_TTL_SECONDS", str(60 * 60 * 24 * 30)))
    except ValueError:
        return 60 * 60 * 24 * 30


def encode_token(user_id: str) -> str:
    now = int(time.time())
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + ttl_seconds(),
        "iss": _ISSUER,
    }
    return jwt.encode(payload, _secret(), algorithm=_ALG)


def decode_token(token: str) -> dict:
    return jwt.decode(
        token, _secret(), algorithms=[_ALG], issuer=_ISSUER,
    )
